#84675 possibly slowed down the build of the generated VariableType file (not worth measuring because the change is easy anyway). With the current way we do codegen, we must instantiate the templated function run_jit_decomposition_with_args_for_jvp for all functions, instead of the just the ones that are differentiable and missing forward AD formulas. Instead, what we should do is modify codegen to be smarter and only generate branch we know we will execute.
Previous codegen:
  auto _tmp = ([&]() {
    if (false && (isFwGradDefined(self))) {
      static c10::OperatorName full_name("aten::log_sigmoid_forward", "");
      static c10::optional<c10::OperatorHandle> opt_op = c10::Dispatcher::singleton().findSchema(full_name);
      return impl::run_jit_decomposition_with_args_for_jvp<std::tuple<at::Tensor, at::Tensor>>("log_sigmoid_forward", *opt_op, ks, self);
    } else {
      at::AutoDispatchBelowADInplaceOrView guard;
      return at::redispatch::log_sigmoid_forward(ks & c10::after_autograd_keyset, self_);
    }
Desired codegen:
  auto _tmp = ([&]() {
      at::AutoDispatchBelowADInplaceOrView guard;
      return at::redispatch::log_sigmoid_forward(ks & c10::after_autograd_keyset, self_);
  }

Issue description
when using make_data_loader on win10 in vs2022 with intel c++ 2022 compiler in debug mode in libtorch, an error occurs.

Code example
Here is my code:
#include <torch/torch.h>

class sample_dataloader : public torch::data::Dataset<sample_dataloader> {
public:
    torch::Tensor rand_val;
    sample_dataloader() {
        rand_val = torch::rand({ 30, 30 }); // random batch of images
    }

    torch::optional<size_t> size() const override {
        return 10;
    }

    torch::data::Example<> get(size_t index) {
        return { rand_val[index], rand_val[index] };
    }
};

int main() {
    auto train_set = sample_dataloader().map(torch::data::transforms::Stack<>());
    int batch_size = 5;
    int num_workers = 0;
    auto dl = torch::data::make_data_loader<torch::data::samplers::SequentialSampler>
        (std::move(train_set), torch::data::DataLoaderOptions().batch_size(batch_size).workers(num_workers));
    for (auto& batch : *dl) {
        auto rand_im = batch.data;
        auto targets = batch.target;
    }
}

